class Solution {
    public int change(int amount, int[] coins) {
        int[] dp = new int[amount + 1];
        dp[0] = 1;

        for (int coin : coins) {
            for (int total = coin; total <= amount; total++) {
                dp[total] += dp[total - coin];
            }
        }
        return dp[amount];
    }
}

class Solution {
    public int change(int amount, int[] coins) {
        int n = coins.length;
        int[][] dp = new int[n + 1][amount + 1];
        for (int i = 0; i <= n; i++) {
            dp[i][0] = 1;
        }

        for (int i = 1; i <= n; i++) {
            int coin = coins[i - 1];
            for (int total = 1; total <= amount; total++) {
                dp[i][total] = dp[i - 1][total];
                if (total >= coin) {
                    dp[i][total] += dp[i][total - coin];
                }
            }
        }
        return dp[n][amount];
    }
}

class Solution {
    public int change(int amount, int[] coins) {
        Integer[][] memo = new Integer[coins.length][amount + 1];
        return count(coins, 0, amount, memo);
    }

    private int count(int[] coins, int index, int remaining, Integer[][] memo) {
        if (remaining == 0) {
            return 1;
        }
        if (index == coins.length) {
            return 0;
        }
        if (memo[index][remaining] != null) {
            return memo[index][remaining];
        }

        int skip = count(coins, index + 1, remaining, memo);
        int take = remaining >= coins[index]
                ? count(coins, index, remaining - coins[index], memo)
                : 0;
        memo[index][remaining] = skip + take;
        return memo[index][remaining];
    }
}

class Solution {
    public int change(int amount, int[] coins) {
        Integer[][] memo = new Integer[coins.length][amount + 1];
        return enumerate(coins, 0, amount, memo);
    }

    private int enumerate(int[] coins, int index, int remaining, Integer[][] memo) {
        if (remaining == 0) {
            return 1;
        }
        if (index == coins.length) {
            return 0;
        }
        if (memo[index][remaining] != null) {
            return memo[index][remaining];
        }

        int ways = 0;
        int coin = coins[index];
        for (int used = 0; used * coin <= remaining; used++) {
            ways += enumerate(coins, index + 1, remaining - used * coin, memo);
        }
        memo[index][remaining] = ways;
        return ways;
    }
}

class Solution {
    public int change(int amount, int[] coins) {
        int[] ways = new int[amount + 1];
        ways[0] = 1;

        for (int coin : coins) {
            int[] next = java.util.Arrays.copyOf(ways, ways.length);
            for (int total = coin; total <= amount; total++) {
                next[total] += next[total - coin];
            }
            ways = next;
        }
        return ways[amount];
    }
}
